// Fetches the brand fonts the bag labels print with (all SIL Open Font
// License) and writes them as base64 string modules under
// lib/intake/labels/fonts/, so the PDF route bundles them on Netlify without
// reading files at run time. Also writes metrics.ts: each font's advance
// widths, so the label layout measures text the same way on the server (PDF)
// and in the browser (SVG preview), and preview = print.
//
// Run once (and again only to change fonts): node scripts/intake-label-fonts.mjs
// The generated files are committed; builds never fetch anything.
import { mkdirSync, writeFileSync } from "node:fs";
import { join } from "node:path";
import { createRequire } from "node:module";

const require = createRequire(import.meta.url);
const fontkit = require("@pdf-lib/fontkit");

const OUT = join(process.cwd(), "lib/intake/labels/fonts");

// role → family and weight. Static instances from the Google Fonts API,
// except IBM Plex Mono: the API's copy has a space glyph fontkit can't read,
// so it comes from the static file in github.com/google/fonts.
const FONTS = {
  display800: { family: "Big Shoulders Display", weight: 800 },
  display900: { family: "Big Shoulders Display", weight: 900 },
  body400: { family: "Schibsted Grotesk", weight: 400 },
  body700: { family: "Schibsted Grotesk", weight: 700 },
  body800: { family: "Schibsted Grotesk", weight: 800 },
  mono600: { family: "IBM Plex Mono", weight: 600, github: "ofl/ibmplexmono/IBMPlexMono-SemiBold.ttf" },
};
const GITHUB_RAW = "https://raw.githubusercontent.com/google/fonts/main/";

const LICENSES = {
  "Big Shoulders Display": "ofl/bigshouldersdisplay/OFL.txt",
  "Schibsted Grotesk": "ofl/schibstedgrotesk/OFL.txt",
  "IBM Plex Mono": "ofl/ibmplexmono/OFL.txt",
};

// Characters the layout measures: printable ASCII, Latin-1 and the few
// typographic marks label text uses. Anything else is measured as "?" (and
// the PDF draws "?" for it when the font lacks it).
const CODEPOINTS = [];
for (let c = 0x20; c <= 0x7e; c++) CODEPOINTS.push(c);
for (let c = 0xa0; c <= 0xff; c++) CODEPOINTS.push(c);
CODEPOINTS.push(0x2013, 0x2014, 0x2018, 0x2019, 0x201c, 0x201d, 0x2022, 0x2026, 0x2116);

async function get(url, as = "text") {
  // An old user agent makes Google Fonts answer with TrueType files
  const res = await fetch(url, { headers: { "User-Agent": "Wget/1.0" } });
  if (!res.ok) throw new Error(`${url}: HTTP ${res.status}`);
  return as === "bytes" ? Buffer.from(await res.arrayBuffer()) : res.text();
}

function cssUrl() {
  const byFamily = {};
  for (const { family, weight, github } of Object.values(FONTS)) {
    if (!github) (byFamily[family] ??= new Set()).add(weight);
  }
  const q = Object.entries(byFamily)
    .map(([family, ws]) => `family=${family.replace(/ /g, "+")}:wght@${[...ws].sort((a, b) => a - b).join(";")}`)
    .join("&");
  return `https://fonts.googleapis.com/css2?${q}`;
}

const css = await get(cssUrl());
const faces = [...css.matchAll(/@font-face\s*{([^}]*)}/g)].map((m) => {
  const body = m[1];
  return {
    family: /font-family:\s*'([^']+)'/.exec(body)?.[1],
    weight: Number(/font-weight:\s*(\d+)/.exec(body)?.[1]),
    url: /src:\s*url\(([^)]+\.ttf)\)/.exec(body)?.[1],
  };
});

mkdirSync(OUT, { recursive: true });
const metrics = {};
for (const [role, { family, weight, github }] of Object.entries(FONTS)) {
  const face = github ? { url: GITHUB_RAW + github } : faces.find((f) => f.family === family && f.weight === weight && f.url);
  if (!face) throw new Error(`No TrueType file for ${family} ${weight}`);
  const bytes = await get(face.url, "bytes");
  const font = fontkit.create(bytes);
  // Fail here, not in the PDF route, if pdf-lib can't use the file
  for (const cp of [32, 65, 0x2026]) if (font.hasGlyphForCodePoint(cp)) void font.glyphForCodePoint(cp).advanceWidth;
  const upm = font.unitsPerEm;
  const widths = {};
  for (const cp of CODEPOINTS) {
    if (!font.hasGlyphForCodePoint(cp)) continue;
    widths[cp] = Math.round((font.glyphForCodePoint(cp).advanceWidth / upm) * 1000);
  }
  metrics[role] = {
    family,
    weight,
    ascent: Math.round((font.ascent / upm) * 1000),
    descent: Math.round((font.descent / upm) * 1000),
    capHeight: Math.round((font.capHeight / upm) * 1000),
    widths,
  };
  writeFileSync(
    join(OUT, `${role}.ts`),
    [
      `// ${family} ${weight} (SIL Open Font License 1.1, see OFL-*.txt here).`,
      "// Generated by scripts/intake-label-fonts.mjs. Do not edit.",
      `const font = "${bytes.toString("base64")}";`,
      "export default font;",
      "",
    ].join("\n"),
  );
  console.log(`${role}: ${family} ${weight}, ${bytes.length} bytes`);
}

writeFileSync(
  join(OUT, "metrics.ts"),
  [
    "// Advance widths (1/1000 em) of the label fonts, by code point.",
    "// Generated by scripts/intake-label-fonts.mjs. Do not edit.",
    "export type LabelFontMetrics = { family: string; weight: number; ascent: number; descent: number; capHeight: number; widths: Record<string, number> };",
    `export const FONT_METRICS: Record<${Object.keys(FONTS).map((r) => JSON.stringify(r)).join(" | ")}, LabelFontMetrics> = ${JSON.stringify(metrics)};`,
    "",
  ].join("\n"),
);

for (const [family, path] of Object.entries(LICENSES)) {
  const text = await get(GITHUB_RAW + path);
  writeFileSync(join(OUT, `OFL-${family.replace(/ /g, "")}.txt`), text);
}
console.log("label fonts written to lib/intake/labels/fonts/");
